connectors.response_body:
{% if response.status_code >= 400 %}
{{ response.body }}
{% else %}
{% set data = response.body | from_json %}
{% set ns = namespace(out=[]) %}
{% for item in data['items'] %}
{% set is_all_day = 'date' in item['start'] %}
{% set start_date = item['start']['date'] if is_all_day else item['start']['dateTime'][:10] %}
{% set start_time = '' if is_all_day else item['start']['dateTime'][11:16] %}
{% set end_time = '' if is_all_day else item['end']['dateTime'][11:16] %}
{% set ns.out = ns.out + [{"id": item['id'], "title": item['summary'] | default('(無題)'), "date": start_date, "time": start_time, "endTime": end_time, "description": item['description'] | default(''), "url": item['htmlLink'] | default(''), "colorId": item['colorId'] | default(''), "isAllDay": is_all_day, "startDateTime": item['start']['dateTime'] | default(''), "endDateTime": item['end']['dateTime'] | default(''), "endDate": item['end']['date'] | default('')}] %}
{% endfor %}
{{ ns.out | json_encode }}
{% endif %}
